import{_ as s,o as t,c as a,a2 as i}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Website and artwork","description":"","frontmatter":{},"headers":[],"relativePath":"docs/development/website.md","filePath":"development/website.md"}'),n={name:"docs/development/website.md"};function o(r,e,d,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="website-and-artwork" tabindex="-1">Website and artwork <a class="header-anchor" href="#website-and-artwork" aria-label="Permalink to &quot;Website and artwork&quot;">​</a></h1><p>The landing page and documentation are one static VitePress site. Search runs in the browser using a local index. The site makes no analytics, external font, image, or search-service requests. Search queries are not persisted.</p><h2 id="build-locally" tabindex="-1">Build locally <a class="header-anchor" href="#build-locally" aria-label="Permalink to &quot;Build locally&quot;">​</a></h2><p>Website development needs Node.js and the pinned package manager. The extension’s runtime does not need Node.js.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span></code></pre></div><p>Build and validate both hosting layouts:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build:subpath</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:test</span></span></code></pre></div><p>The root artifact is <code>docs/.vitepress/dist/</code>. The <code>/kittyscape/</code> artifact is <code>docs/.vitepress/dist-subpath/</code>. Both are static files.</p><h2 id="github-pages" tabindex="-1">GitHub Pages <a class="header-anchor" href="#github-pages" aria-label="Permalink to &quot;GitHub Pages&quot;">​</a></h2><p><code>.github/workflows/deploy-pages.yml</code> deploys the <code>/kittyscape/</code> artifact after a push to <code>main</code> or a manual run on <code>main</code>. The landing page resolves at the project Pages root, and the documentation entry point resolves at <code>/docs/</code> relative to that site. For this repository, those URLs are <code>https://sandwichfarm.github.io/kittyscape/</code> and <code>https://sandwichfarm.github.io/kittyscape/docs/</code>.</p><p>Before the first deployment, select <strong>GitHub Actions</strong> as the Pages publishing source in the repository’s Pages settings. Pull requests build through local and CI checks but do not deploy a preview site. The workflow keeps one deployment in flight and publishes only the validated static artifact.</p><p>Browser checks use an existing Playwright installation. Set <code>PLAYWRIGHT_PATH</code> to its module path if it is not available at <code>/usr/lib/node_modules/playwright</code>. Browser binaries must already be installed. The verifier records unavailable browsers as a failed acceptance gate, rather than downloading them. Accessibility checks use an existing <code>axe-core</code> installation. Set <code>AXE_PATH</code> to its <code>axe.min.js</code> file when it is outside the normal module path. Neither test tool is added to the runtime bundle. For an isolated WebKit library wrapper, set <code>WEBKIT_EXECUTABLE_PATH</code> to that existing launcher. The headless suite includes a 720 CSS-pixel viewport at scale factor two as a layout check. Native browser zoom is verified separately:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/site/zoom.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/site/webkit_zoom.py</span></span></code></pre></div><p>Run these sequentially: both reserve display <code>:103</code>, verify ownership, and refuse existing display resources. The first uses native keyboard input in Chromium, Firefox, and WebKit. WebKit’s MiniBrowser shortcuts reach 207.36%, so that script retains an unverified exact-200% row. The second uses WebKitGTK’s public zoom API to set exactly <code>2.0</code>, checks the resulting CSS viewport and native window dimensions, and records its own proof. Read the combined evidence in the <a href="/evidence/release.json">release record</a>.</p><p>These native runners use the existing browser and library paths recorded in their source. Confirm those paths and prerequisites on another machine. They create their test state under <code>/tmp</code> and leave desktop configuration and installed browser files intact. Keep both built artifacts unchanged while a run is active.</p><p>To rerun only a failing browser during development, use <code>node tests/site/browser.mjs firefox</code>, for example. Final acceptance includes the full headless suite and native zoom/keyboard evidence; filtered runs are labeled.</p><h2 id="dependency-choice" tabindex="-1">Dependency choice <a class="header-anchor" href="#dependency-choice" aria-label="Permalink to &quot;Dependency choice&quot;">​</a></h2><p>On September 15, 2026, the npm registry’s stable VitePress release was <strong>1.6.4</strong>, published August 5, 2025. The <code>next</code> release was a prerelease, so this project pins the stable release. The installed <strong>pnpm 11.3.0</strong>, published May 24, 2026, is pinned in <code>package.json</code>. Dependency resolution uses a seven-day minimum release age.</p><p>The theme and search APIs were checked against the <a href="https://github.com/vuejs/vitepress/tree/v1.6.4" target="_blank" rel="noreferrer">VitePress 1.6.4 source</a>. The theme imports <code>theme-without-fonts</code>; all typography uses the visitor’s system fonts.</p><p>The pinned dependency patch in <code>patches/</code> corrects local-search semantics and the theme switch’s initial accessible name. Keep the patch, <code>pnpm-workspace.yaml</code>, and <code>pnpm-lock.yaml</code> together when copying the source bundle. The existing upstream MIT notice is preserved.</p><h2 id="asset-provenance" tabindex="-1">Asset provenance <a class="header-anchor" href="#asset-provenance" aria-label="Permalink to &quot;Asset provenance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Origin</th><th>Use</th></tr></thead><tbody><tr><td><code>docs/public/cat-mark.svg</code></td><td>Original paths authored for Kittyscape on September 15, 2026.</td><td>Navigation mark and favicon.</td></tr><tr><td><code>docs/public/terminal-cat.svg</code></td><td>Original vector landscape, terminal, and resting cat authored for Kittyscape on September 15, 2026.</td><td>Static landing illustration.</td></tr></tbody></table><p>The artwork does not copy kitty’s mascot and contains no fetched or third-party artwork. The terminal scene is an illustration, not evidence of a running extension. The cat itself is decorative. The image’s text alternative describes the terminal scene.</p><p>A project license has not been selected. Publication still requires a licensing decision and review of the bundled dependency notices. The local artwork’s provenance does not grant a publication license.</p><h2 id="design-constraints" tabindex="-1">Design constraints <a class="header-anchor" href="#design-constraints" aria-label="Permalink to &quot;Design constraints&quot;">​</a></h2><p>Warm ivory, charcoal, muted sage, and small peach accents carry the visual design. Dark mode uses warm dark surfaces. The layout keeps a 960 px home content width, fine borders, modest radii, and one illustration shadow. There is no decorative animation. Reduced-motion settings suppress inherited theme transitions.</p><p>Browser checks cover navigation, open local-search states, light/dark mode, mobile overflow, keyboard focus, zoom, JavaScript-disabled reading, and third-party requests. Site screenshots establish presentation; kitty runtime behavior has its own <a href="./../reference/compatibility.html">qualification record</a>.</p>`,27)])])}const b=s(n,[["render",o]]);export{u as __pageData,b as default};
